select jsonb_build_object(
'functions',(select jsonb_agg(x order by x.schema,x.name,x.args) from (select n.nspname schema,p.proname name,pg_get_function_identity_arguments(p.oid) args,md5(pg_get_functiondef(p.oid)) definition_hash from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='aura_private' or (n.nspname='public' and p.proname like 'aura_%')) x),
'tables',(select jsonb_agg(x order by x.schema,x.name) from(select n.nspname schema,c.relname name,c.relrowsecurity rls from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and (n.nspname='aura_private' or (n.nspname='public' and c.relname like 'aura_%'))) x),
'policies',(select jsonb_agg(x order by x.schema,x.table_name,x.name) from(select schemaname schema,tablename table_name,policyname name,permissive,roles,cmd,qual,with_check from pg_policies where schemaname='aura_private' or(schemaname='public' and tablename like 'aura_%')) x),
'columns',(select jsonb_agg(x order by x.schema,x.table_name,x.position) from(select table_schema schema,table_name,column_name name,ordinal_position position,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema='aura_private' or(table_schema='public' and table_name like 'aura_%')) x),
'indexes',(select jsonb_agg(x order by x.schema,x.name) from(select schemaname schema,indexname name,indexdef definition from pg_indexes where schemaname='aura_private' or(schemaname='public' and tablename like 'aura_%')) x),
'triggers',(select coalesce(jsonb_agg(x order by x.schema,x.name),'[]') from(select n.nspname schema,t.tgname name,pg_get_triggerdef(t.oid) definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname='aura_private' or(n.nspname='public' and c.relname like 'aura_%'))) x),
'constraints',(select coalesce(jsonb_agg(x order by x.schema,x.table_name,x.name),'[]') from(select n.nspname schema,c.relname table_name,k.conname name,pg_get_constraintdef(k.oid) definition from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='aura_private' or(n.nspname='public' and c.relname like 'aura_%')) x),
'privileges',(select jsonb_agg(x order by x.schema,x.name,x.role,x.kind) from(
 select n.nspname schema,c.relname name,r.role,'table' kind,jsonb_build_object('select',has_table_privilege(r.role,c.oid,'SELECT'),'insert',has_table_privilege(r.role,c.oid,'INSERT'),'update',has_table_privilege(r.role,c.oid,'UPDATE'),'delete',has_table_privilege(r.role,c.oid,'DELETE'),'truncate',has_table_privilege(r.role,c.oid,'TRUNCATE')) access from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join(values('anon'),('authenticated')) r(role) where c.relkind='r' and(n.nspname='aura_private' or(n.nspname='public' and c.relname like 'aura_%'))
 union all select n.nspname,p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',r.role,'function',jsonb_build_object('execute',has_function_privilege(r.role,p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join(values('anon'),('authenticated')) r(role) where n.nspname='aura_private' or(n.nspname='public' and p.proname like 'aura_%')
 )x)
) catalog;
